import re

# Fix useSessionSend.ts — both fixes
path = "packages/web-core/src/features/workspace-chat/model/hooks/useSessionSend.ts"
with open(path) as f:
    src = f.read()

# Fix 1: add ApiError import
src = src.replace(
    "import { executionProcessesApi, queueApi, sessionsApi } from '@/shared/lib/api';",
    "import { ApiError, executionProcessesApi, queueApi, sessionsApi } from '@/shared/lib/api';"
)

# Fix 2: replace the inject catch block — distinguish 4xx (process gone) from transient
old_catch = """            } catch (e) {
              // The HTTP call failed — most likely because the process exited
              // between our status check and this call. Route to followUp so
              // we start a fresh execution rather than queuing for an event
              // that may never fire.
              console.warn(
                '[useSessionSend] inject-message failed, process may have exited — falling back to followUp:',
                e
              );
              processExited = true;
            }"""

new_catch = """            } catch (e) {
              // Only treat definitive "process not running" responses (4xx) as
              // confirmation that the process exited. Transient failures (network
              // drop, 5xx, proxy error) should queue rather than spawn a new
              // execution while the process may still be alive.
              const isProcessGone =
                e instanceof ApiError && e.status !== undefined && e.status < 500;
              if (isProcessGone) {
                console.warn(
                  '[useSessionSend] inject-message: process no longer running — falling back to followUp:',
                  e
                );
                processExited = true;
              } else {
                console.warn(
                  '[useSessionSend] inject-message failed transiently — queuing instead:',
                  e
                );
              }
            }"""

src = src.replace(old_catch, new_catch)

with open(path, 'w') as f:
    f.write(src)

print("useSessionSend.ts patched")
print("ApiError import:", "ApiError," in src)
print("isProcessGone check:", "isProcessGone" in src)
PYEOF

